// Dimension-wheel "shadow" icons (2026-09-22, direct instruction: "the
// wheel rhombus itself as if it is a projection into 2D from the
// various dimensions... 2D flat diamond, 3D a 3D rhombus etc" /
// "multi-dimensional shadows"). Real math, not decoration: each icon is
// the genuine 2D shadow (orthogonal projection) of the zonotope
// generated by N unit vectors evenly spaced across a half-circle (angles
// k*180/N for k=0..N-1) -- the same real construction this session
// already used for RD's own 4-vector body-diagonal zonotope (see core/
// lattice.js's rdQuarterPieces header), generalized down to 2D where the
// full boundary has a simple, exact closed form (unlike 3D+, no Bohne-
// Dress tiling theorem needed just for an outline): walk v0, v1, ...,
// v(N-1), then -v0, -v1, ..., -v(N-1) -- a real, closed, convex 2N-gon.
//
// N=2 is a genuine special case, not the generic formula: 2 vectors at
// 90 degrees give a rectangle, not a rhombus, so 2D keeps the simple
// flat-diamond CSS clip-path treatment already shipped (rhombic-wheel-
// 3d.js's own scoped CSS) rather than going through this file at all.
// N=3 (3D) gets its own explicit 3-rhombi construction too -- the exact
// same "3 faces sharing one corner" fact as RD's own zonotope decomposition,
// just 2D -- because that's the real, well-known closed form for 3
// vectors specifically (the classic isometric-cube-corner drawing), and
// it lets each face get its own real depth-shading. N>=4 (4D/5D/6D,
// still unbuilt) draws only the real outer boundary -- no internal
// facet subdivision is computed or claimed, matching this app's own
// "don't overclaim precision for content that doesn't exist yet"
// discipline (RHOMBIVERSE_PRINCIPLES.md section 0).

function vec(n, R, k) {
  const a = (Math.PI * k) / n;
  return [R * Math.cos(a), R * Math.sin(a)];
}
function add(a, b) { return [a[0] + b[0], a[1] + b[1]]; }
function pts(arr) { return arr.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(' '); }

function threeDShadow(R) {
  const v0 = vec(3, R, 0), v1 = vec(3, R, 1), v2 = vec(3, R, 2);
  const o = [0, 0];
  const rA = [o, v0, add(v0, v1), v1];
  const rB = [o, v1, add(v1, v2), v2];
  const rC = [o, v2, add(v2, v0), v0];
  return `
    <polygon points="${pts(rA)}" fill="currentColor" opacity="0.85"/>
    <polygon points="${pts(rB)}" fill="currentColor" opacity="0.55"/>
    <polygon points="${pts(rC)}" fill="currentColor" opacity="0.3"/>`;
}

function outlineShadow(n, R) {
  let p = [0, 0];
  const boundary = [p];
  for (let k = 0; k < n; k++) { p = add(p, vec(n, R, k)); boundary.push(p); }
  for (let k = 0; k < n; k++) { p = [p[0] - vec(n, R, k)[0], p[1] - vec(n, R, k)[1]]; boundary.push(p); }
  const cx = boundary.reduce((s, q) => s + q[0], 0) / boundary.length;
  const cy = boundary.reduce((s, q) => s + q[1], 0) / boundary.length;
  const centered = boundary.map(([x, y]) => [x - cx, y - cy]);
  return `<polygon points="${pts(centered)}" fill="none" stroke="currentColor" stroke-width="2.5"/>`;
}

const DIMENSION_N = { '3D': 3, '4D': 4, '5D': 5, '6D': 6 };

// Returns null for 2D -- see this file's own header for why that stays
// the plain CSS-clip-path diamond instead of going through here.
export function dimensionShadowIcon(label) {
  const n = DIMENSION_N[label];
  if (!n) return null;
  const R = 22;
  const inner = n === 3 ? threeDShadow(R) : outlineShadow(n, R);
  return `<svg viewBox="-30 -30 60 60" width="1em" height="1em" role="img" aria-label="${label} shadow">${inner}</svg>`;
}
